import{_ as a,c as s,o,ah as l,ao as i,ap as n}from"./chunks/framework.Dq2_gudl.js";const h=JSON.parse('{"title":"Pets in Heaven — Ellos, el Cielo y Tu Duelo","description":"Para quien perdió a un compañero animal: lo que la Biblia dice sobre los animales, la eternidad y el cuidado de Dios. Cuatro lecturas tiernas.","frontmatter":{"title":"Pets in Heaven — Ellos, el Cielo y Tu Duelo","description":"Para quien perdió a un compañero animal: lo que la Biblia dice sobre los animales, la eternidad y el cuidado de Dios. Cuatro lecturas tiernas."},"headers":[],"relativePath":"es/pets-in-heaven/index.md","filePath":"es/pets-in-heaven/index.md"}'),r={name:"es/pets-in-heaven/index.md"};function t(p,e,c,d,u,m){return o(),s("div",null,[...e[0]||(e[0]=[l('<div class="pl-quote"><p>«Después de que se fue, lo único que quería saber era esto: ¿está bien? ¿Volveremos a vernos?»</p><p class="pl-quote-soft">La Biblia no responde todo en una frase, pero da suficiente luz para ver esperanza en la noche más oscura.</p></div><section class="pl-section"><h2>Antes de empezar</h2><p class="pl-lead">Este no es un lugar que te pida «superarlo pronto». Estas cuatro lecturas son para ti, que todavía lo extrañas.</p><p>Perder a un compañero animal es un duelo muy particular. La gente dice «era solo un perro» o «consigue otro» — pero sabes que no es verdad. Él reconocía el sonido de tus pasos al llegar. En tu año más difícil, se quedó pegado a tus pies. Lo que se fue con él fue la primera mirada que te recibía cada mañana.</p><p>La Biblia, de hecho, dice mucho sobre los animales. Dios los creó, los alimenta, hace un pacto con ellos y los coloca dentro del mundo que promete renovar. Estos versículos no prueban que «cada mascota está en el cielo» — la Biblia no promete eso — pero revelan algo tierno: <strong>en el plan de Dios, los animales nunca fueron extras desechables.</strong></p><p>Que lo que encuentres aquí sea más que versículos: que sea el Dios que recuerda hasta a un gorrión, recordando al tuyo.</p></section><section class="pl-section"><h2>Cuatro lecturas para ti</h2><div class="pl-new-grid"><div class="pl-new-card"><h3><a href="/es/pets-in-heaven/will-i-see-my-pet-again">¿Volveré a ver a mi mascota?</a></h3><p>La esperanza de la Biblia para los animales y el cielo: la creación misma espera la redención, y la nueva creación todavía tiene animales.</p><p class="pl-quote-soft">Romanos 8:19-22 · Isaías 11:6-9 · Apocalipsis 21:4-5</p></div><div class="pl-new-card"><h3><a href="/es/pets-in-heaven/not-one-sparrow-forgotten">Ni un gorrión es olvidado</a></h3><p>Era tan pequeño — ¿lo recordará el mundo? Jesús dijo que ni un gorrión cae sin que el Padre lo sepa.</p><p class="pl-quote-soft">Mateo 10:29-31 · Salmos 147:9 · Salmos 36:6</p></div><div class="pl-new-card"><h3><a href="/es/pets-in-heaven/rainbow-bridge-covenant">Más allá del Puente del Arcoíris</a></h3><p>«Puente del Arcoíris» es una imagen hermosa, y la Biblia realmente tiene un arcoíris: el pacto eterno de Dios con <em>todo ser viviente</em>.</p><p class="pl-quote-soft">Génesis 9:9-13 · Isaías 65:25 · Apocalipsis 5:13</p></div><div class="pl-new-card"><h3><a href="/es/pets-in-heaven/permission-to-grieve">Permiso para llorar</a></h3><p>Dios guarda tus lágrimas en un frasco. El duelo no es falta de fe: es amor que continúa.</p><p class="pl-quote-soft">Salmos 56:8 · Salmos 34:18 · Mateo 5:4</p></div></div></section><section class="pl-section"><h2>Cómo leer estas páginas</h2><div class="pl-moment-grid"><div class="pl-moment"><span class="pl-moment-icon">🕯️</span><h3>Despacio — no todo de una vez</h3><p>Un párrafo es suficiente. Si un versículo te hace llorar, detente ahí. No es debilidad; es amor en movimiento.</p></div><div class="pl-moment"><span class="pl-moment-icon">📝</span><h3>Pon su nombre en el versículo</h3><p>Cuando leas «Él da alimento a las bestias», intenta decir su nombre en esa frase. Dios también lo cuidó así.</p></div><div class="pl-moment"><span class="pl-moment-icon">🕊️</span><h3>Después, dile una cosa</h3><p>No necesita ser bonito. «Te extraño» es suficiente. Si quieres decir más, el diario guiado de PetLoss se queda contigo.</p></div></div></section><section class="pl-section"><h2>Todos los versículos en un solo lugar</h2><p class="pl-lead">Todos los pasajes citados en estas cuatro lecturas, reunidos aquí para releerlos y buscarlos con calma.</p><div class="pl-verse-groups"><div class="pl-verse-group"><h3><a href="/es/pets-in-heaven/will-i-see-my-pet-again">¿Volveré a ver a mi mascota?</a></h3><ul class="pl-verse-list"><li>Romanos 8:19-22</li><li>Isaías 11:6-9</li><li>Apocalipsis 21:4-5</li><li>Salmos 36:6</li></ul></div><div class="pl-verse-group"><h3><a href="/es/pets-in-heaven/not-one-sparrow-forgotten">Ni un gorrión es olvidado</a></h3><ul class="pl-verse-list"><li>Mateo 10:29-31</li><li>Salmos 147:9</li><li>Salmos 36:6</li><li>Salmos 50:10-11</li></ul></div><div class="pl-verse-group"><h3><a href="/es/pets-in-heaven/rainbow-bridge-covenant">Más allá del Puente del Arcoíris</a></h3><ul class="pl-verse-list"><li>Génesis 9:9-13</li><li>Isaías 65:25</li><li>Apocalipsis 5:13</li><li>Salmos 150:6</li></ul></div><div class="pl-verse-group"><h3><a href="/es/pets-in-heaven/permission-to-grieve">Permiso para llorar</a></h3><ul class="pl-verse-list"><li>Salmos 56:8</li><li>Salmos 34:18</li><li>Salmos 147:3</li><li>Mateo 5:4</li><li>Juan 11:35</li><li>Apocalipsis 21:4</li></ul></div></div></section><div class="pl-cta"><h2>Que aquí seas sostenido con ternura.</h2><p>Si quieres un lugar para guardar sus fotos y escribir lo que no alcanzaste a decir, PetLoss se quedará en silencio a tu lado — sin cuenta, sin subidas, totalmente offline.</p><a class="pl-download" href="https://apps.apple.com/us/app/petloss-memorial-healing/id6757967412">Descargar en el App Store</a><p class="pl-disclaimer">Estas lecturas ofrecen reflexión de fe y compañía emocional; no constituyen consejo médico, psicológico ni terapéutico. Si el duelo te impide funcionar durante mucho tiempo, busca a un profesional licenciado o una línea de apoyo local. Las citas bíblicas son de la King James Version (KJV).</p></div><div class="pl-bible"><h3>Deja que la Palabra te siga acompañando</h3><p>Todos los versículos de estas cuatro lecturas provienen de la Biblia. Con Rainbow Bible puedes leer las Escrituras en cualquier momento y poner un widget con el versículo del día: una pequeña luz en los días en que lo echas de menos.</p><div class="pl-bible-shots"><figure><img src="'+i+'" alt="Widget de Rainbow Bible mostrando 2 Timoteo 2:13" loading="lazy"><figcaption>Versículo del día en tu pantalla</figcaption></figure><figure><img src="'+n+'" alt="Rainbow Bible — tema Mascotas en el cielo mostrando Mateo 10:29-31" loading="lazy"><figcaption>Lee las Escrituras en Mascotas en el cielo</figcaption></figure></div><a class="pl-bible-download" href="https://apps.apple.com/app/id6756217525">Descargar Rainbow Bible en el App Store</a></div>',7)])])}const g=a(r,[["render",t]]);export{h as __pageData,g as default};
